{
  "name": "Auction house",
  "clock": {"rounds": "$inputs.horizon", "unit": "round"},
  "brief": {
    "situation": "An auction house is selling paintings to collectors. One lot comes under the hammer each round. Every collector, you among them, starts with the cash shown for it and a private opinion of what each painting is worth. Those private values are yours alone — nobody else can see them.",
    "rules": "Lots 1 to 3 sell by open ascending auction: collectors take turns raising the standing high bid by at least {$inputs.increment|money}; everyone can see the current high bid; the lot closes as soon as a full round of turns passes with no new bid, and the standing high bidder buys at that bid. Lots 4 to 6 sell by sealed bid: every collector privately submits at most one bid; the highest bid wins and pays exactly what it bid; if two bids tie, the one submitted first wins. You can never bid more cash than you hold. Winners pay the house. Every painting is sold at most once.",
    "roles": {
      "collector": "You are a collector. Your private values for lots 1 to 6 are {$actor.values|list} and you hold {$actor.cash|money}. Bid only up to what a painting is worth to you, and never more cash than you have."
    }
  },
  "inputs": {
    "horizon": {"type": "int", "default": 6, "min": 1, "display": "number", "label": "Rounds (one lot per round)"},
    "increment": {"type": "int", "default": 5, "min": 1, "display": "number", "label": "Minimum raise ($)"},
    "start_price": {"type": "int", "default": 5, "min": 0, "display": "number", "label": "Opening bid ($)"},
    "collectors": {"type": "table", "display": "table", "label": "Collectors", "fields": {
      "name": {"type": "text", "required": true},
      "cash": {"type": "int", "default": 300, "min": 0},
      "values": {"type": "list", "required": true, "items": {"type": "int", "min": 0}}
    }, "default": [
      {"name": "ann", "cash": 300, "values": [80, 120, 60, 200, 90, 150]},
      {"name": "bob", "cash": 300, "values": [100, 90, 140, 70, 180, 60]},
      {"name": "cid", "cash": 300, "values": [60, 60, 80, 150, 120, 210]},
      {"name": "dee", "cash": 300, "values": [140, 70, 90, 60, 70, 100]},
      {"name": "eve", "cash": 300, "values": [70, 150, 70, 110, 60, 80]},
      {"name": "fin", "cash": 300, "values": [90, 100, 110, 90, 100, 90]}
    ]},
    "lots": {"type": "table", "display": "table", "label": "Lots", "fields": {
      "lot": {"type": "int", "required": true},
      "format": {"type": "enum", "values": ["english", "sealed"], "default": "english"}
    }, "default": [
      {"lot": 1, "format": "english"},
      {"lot": 2, "format": "english"},
      {"lot": 3, "format": "english"},
      {"lot": 4, "format": "sealed"},
      {"lot": 5, "format": "sealed"},
      {"lot": 6, "format": "sealed"}
    ]}
  },
  "world": {
    "active": 0,
    "format": "",
    "high_bid": 0,
    "high_bidder": {"type": "any", "default": null},
    "quiet_turns": 0,
    "seal_seq": 0,
    "turn_bid": false,
    "cash_start": 0
  },
  "types": {
    "collector": {
      "agent": true,
      "props": {
        "cash": {"type": "int", "default": 300, "min": 0},
        "values": {"type": "list", "default": [], "private": true, "description": "Private value per lot (index 0 = lot 1)."},
        "sealed_bid": {"type": "int", "default": 0, "min": 0},
        "sealed_seq": {"type": "int", "default": 0, "min": 0}
      }
    },
    "lot": {
      "props": {
        "index": {"type": "int", "default": 0},
        "format": {"type": "text", "default": "english"},
        "status": {"type": "text", "default": "open"},
        "winner": {"type": "any", "default": null},
        "price": {"type": "any", "default": null}
      }
    },
    "house": {
      "props": {"cash": {"type": "int", "default": 0, "min": 0}}
    }
  },
  "entities": {
    "house": {"type": "house", "name": "Auction house"}
  },
  "population": [
    {"type": "collector", "from": "$inputs.collectors", "id": "{$row.name}", "name": "{$row.name}",
     "props": {"cash": "$row.cash", "values": "$row.values"}},
    {"type": "lot", "from": "$inputs.lots", "id": "lot_{$row.lot}", "name": "Lot {$row.lot}",
     "props": {"index": "$row.lot", "format": "$row.format"}}
  ],
  "stages": [
    {
      "name": "english",
      "when": "$world.format == english",
      "actions": ["bid"],
      "turns": "sequential",
      "who": "collector",
      "order": "seat",
      "max_actions": 1,
      "max_calls": 8,
      "until": "$world.quiet_turns >= $count(collector)",
      "passes": 40,
      "brief": "Lot {$world.active} is open. Raise the high bid by at least {$inputs.increment|money}, or end your turn. The lot closes after a full round with no new bid.",
      "on_wake": ["$world.turn_bid = false"],
      "on_turn_end": ["$world.quiet_turns = 0 if $world.turn_bid else $world.quiet_turns + 1"],
      "on_exit": [
        {"if": "$world.high_bidder == null", "then": [
          {"each": "lot", "where": "$it.index == $world.active", "do": [
            "$it.status = unsold", "$it.winner = null", "$it.price = null"]}
        ], "else": [
          {"transfer": "cash", "from": "$entity($world.high_bidder)", "to": "$entity(house)", "amount": "$world.high_bid"},
          {"each": "lot", "where": "$it.index == $world.active", "do": [
            "$it.status = sold", "$it.winner = $world.high_bidder", "$it.price = $world.high_bid"]}
        ]}
      ]
    },
    {
      "name": "sealed",
      "when": "$world.format == sealed",
      "actions": ["submit_bid"],
      "turns": "sequential",
      "who": "collector",
      "order": "seat",
      "max_actions": 1,
      "max_calls": 8,
      "passes": 1,
      "brief": "Lot {$world.active} is sold by sealed bid. Privately submit one bid, or end your turn without bidding. Highest bid wins and pays what it bid; ties go to the earliest submission."
    }
  ],
  "events": [
    {"phase": "start", "at": 1, "do": ["$world.cash_start = $sum(collector, $it.cash)"]},
    {"phase": "start", "do": [
      {"if": "$round <= $len($inputs.lots)", "then": [
        "$world.active = $round",
        "$world.format = $inputs.lots[$round - 1].format",
        "$world.high_bid = 0",
        "$world.high_bidder = null",
        "$world.quiet_turns = 0",
        "$world.seal_seq = 0",
        "$world.turn_bid = false",
        {"each": "collector", "do": ["$it.sealed_bid = 0", "$it.sealed_seq = 0"]},
        {"each": "lot", "where": "$it.index == $round", "do": ["$it.status = open"]}
      ]}
    ]},
    {"phase": "end", "when": "$world.format == sealed", "do": [
      "$winners = $top(collector, [$it.sealed_bid, -$it.sealed_seq], 1, $it.sealed_bid > 0)",
      {"if": "$len($winners) == 0", "then": [
        {"each": "lot", "where": "$it.index == $world.active", "do": [
          "$it.status = unsold", "$it.winner = null", "$it.price = null"]}
      ], "else": [
        "$w = $winners[0]",
        {"transfer": "cash", "from": "$w", "to": "$entity(house)", "amount": "$w.sealed_bid"},
        {"each": "lot", "where": "$it.index == $world.active", "do": [
          "$it.status = sold", "$it.winner = $w.id", "$it.price": "$w.sealed_bid"]}
      ]}
    ]}
  ],
  "actions": {
    "bid": {
      "by": "collector",
      "description": "Raise the standing high bid on the painting now under the hammer. The bid must exceed the current high bid by at least the increment and cannot exceed your cash.",
      "when": [
        "$world.format == english",
        {"expr": "$actor.id != $world.high_bidder", "why": "You already hold the standing high bid."},
        {"expr": "$actor.cash >= $world.high_bid + $inputs.increment", "why": "You cannot cover the minimum raise."}
      ],
      "params": {
        "price": {"type": "int", "min": "$world.high_bid + $inputs.increment", "max": "$actor.cash",
                  "description": "Your new high bid in dollars."}
      },
      "do": ["$world.high_bid = $params.price", "$world.high_bidder = $actor.id", "$world.turn_bid = true"],
      "outcome": "You hold the high bid on lot {$world.active} at {$params.price|money}.",
      "announce": "{$actor.name} bids {$params.price|money}."
    },
    "submit_bid": {
      "by": "collector",
      "description": "Privately submit your one sealed bid for the painting on the block. It cannot exceed your cash.",
      "when": [
        "$world.format == sealed",
        {"expr": "$actor.sealed_bid == 0", "why": "You have already submitted a bid for this lot."}
      ],
      "params": {
        "price": {"type": "int", "min": 1, "max": "$actor.cash", "description": "Your sealed bid in dollars."}
      },
      "private": true,
      "do": ["$world.seal_seq += 1", "$actor.sealed_bid = $params.price", "$actor.sealed_seq = $world.seal_seq"],
      "outcome": "You sealed {$params.price|money} for lot {$world.active} (submitted {$world.seal_seq})."
    }
  },
  "views": {
    "cash": {"show": "You hold {$actor.cash|money}."},
    "values": {"for": "collector", "show": "Your private values — lot 1 {$actor.values[0]|money}, lot 2 {$actor.values[1]|money}, lot 3 {$actor.values[2]|money}, lot 4 {$actor.values[3]|money}, lot 5 {$actor.values[4]|money}, lot 6 {$actor.values[5]|money}."},
    "high_bid": {"when": "$world.format == english", "show": "Lot {$world.active} under the hammer: high bid {$world.high_bid|money} by {$world.high_bidder or 'no one yet'}."},
    "board": {"title": "Lots", "of": "lot", "sort": "$it.index",
      "show": "Lot {$it.index} ({$it.format}): {$it.status} — winner {$it.winner or 'none'}, price {$it.price or 0}."},
    "spectator": {"for": "spectator", "title": "Results", "of": "lot", "sort": "$it.index",
      "show": "Lot {$it.index} ({$it.format}): {$it.status}, winner {$it.winner or 'none'} at {$it.price or 0}."}
  },
  "metrics": {
    "house_revenue": "$entity(house).cash",
    "lots_sold": "$count(lot, $it.status == sold)"
  },
  "outputs": {
    "lots": {"type": "list", "expr": "$map($sort(lot, $it.index), {lot: $it.index, format: $it.format, winner: $it.winner, price: $it.price})"},
    "house_revenue": {"type": "number", "expr": "$entity(house).cash", "format": "money"},
    "cash_start_total": {"type": "number", "expr": "$world.cash_start", "format": "money"},
    "cash_end_total": {"type": "number", "expr": "$sum(collector, $it.cash)", "format": "money"}
  },
  "invariants": [
    {"expr": "$sum(collector, $it.cash) + $entity(house).cash == $world.cash_start",
     "why": "Cash only moves from collectors to the house.", "check": "round"},
    {"expr": "$all(lot, $it.status != sold or $it.winner != null)",
     "why": "A sold lot always names a winner.", "check": "round"}
  ]
}

